for iteration in range(100):
 boxes=[t.get_window_extent(renderer).expanded(1.13,1.15) for t in texts];moves=[[0.,0.] for _ in texts];collisions=0
 for i in range(len(texts)):
  for k in range(i+1,len(texts)):
   a,b=boxes[i],boxes[k]
   if a.overlaps(b):
    collisions+=1;dy=min(a.y1,b.y1)-max(a.y0,b.y0)+1;direction=1 if (a.y0+a.y1)>=(b.y0+b.y1) else -1
    moves[i][1]+=direction*dy*.52;moves[k][1]-=direction*dy*.52
 if not collisions:break
 for i,t in enumerate(texts):
  if moves[i]!=[0.,0.]:
   pixel=ax.transData.transform(t.get_position());pixel+=moves[i];t.set_position(ax.transData.inverted().transform(pixel))
for t,(x,y) in zip(texts,anchors):
 if abs(t.get_position()[1]-y)>.025:ax.plot([x,t.get_position()[0]],[y,t.get_position()[1]],color='#7a8d90',lw=.5,zorder=0)
fig.savefig(G/'wording_similarity.png',dpi=160);plt.close(fig)
