style='''*{box-sizing:border-box}body{margin:0;background:#f9faf7;color:#18313b;font:16px/1.65 system-ui,Segoe UI,sans-serif}header,main,footer{max-width:1280px;margin:auto;padding:32px}header{padding-top:60px}h1,h2{font-family:Georgia,serif;line-height:1.15}h1{font-size:clamp(36px,5vw,64px);max-width:1050px;margin:15px 0 24px}h2{font-size:32px}h3{font-size:19px}a{color:#176b64}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#176b64}.lead{font-size:21px;color:#516870;max-width:1050px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:30px 0}.stat{padding:20px;background:#e7efe9;border-radius:5px}.stat b{display:block;font:700 39px Georgia,serif}.stat span,small,.small{font-size:13px;color:#516870}nav{display:flex;flex-wrap:wrap;gap:22px}section{padding:35px 0;border-top:1px solid #d7e0d9}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:#fff;border:1px solid #d7e0d9;padding:22px;border-radius:6px}.callout{border-left:4px solid #176b64;background:#e7efe9;padding:18px;margin:20px 0}.amber{background:#f8efe4;border-color:#a36d3f}.scroll{overflow:auto;max-height:620px;border:1px solid #d7e0d9}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:13px;text-align:left;vertical-align:top;border-bottom:1px solid #d7e0d9}th{position:sticky;top:0;background:#e7efe9;z-index:1}input,select,button{font:inherit;padding:10px;margin:5px 5px 10px 0;border:1px solid #bacbbf;border-radius:4px;background:#fff;color:#18313b}input{min-width:250px}button{cursor:pointer}button:hover{background:#e7efe9}figure{margin:24px 0}figure img{width:100%;height:auto}figcaption{font-size:13px;color:#516870}.verbatim{white-space:pre-wrap;direction:auto;border-left:3px solid #86aa9e;background:#f2f5ef;padding:16px;font:15px/1.75 Georgia,serif;max-height:480px;overflow:auto}.tag{display:inline-block;background:#e7efe9;font-size:12px;padding:3px 9px;margin:4px}.clause{background:#fff;border:1px solid #d7e0d9;border-radius:6px;padding:22px;margin:18px 0}details{margin:12px 0}pre{white-space:pre-wrap;word-break:break-word;font-size:12px}li{margin:9px 0}@media(max-width:760px){header,main,footer{padding:22px}.stats,.grid{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}h1{font-size:38px}input,select{max-width:100%}}'''
feature_rows=''.join(f'<tr><td>{e(by[k]["label"])}</td><td>{by[k]["count"]}/{R["legal_n"]}</td><td>{e(", ".join(by[k]["countries"]))}</td></tr>' for k in keys)
lit_rows=''.join(f'<tr><td><a href="{e(p["url"])}" target="_blank" rel="noopener">{e(p["citation"])}</a><br><small>{e(p["scope"])} · {e(p["observation_period"])}</small></td><td>{e(p["finding"])}</td><td>{e(p["comparison"])}</td></tr>' for p in P[:4])
nlp_legal=sum(d['primary_legal_comparison'] for d in read(F/'analysis/model_documents.json'))
orig=next(x for x in R['readability_sensitivity'] if x['sample']=='excluding_official_translation')
text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>International regulatory reliance · wording, evidence and implementation</title><style>{style}</style></head><body>
<header><div class="eyebrow">International pharmaceutical regulation · legal-text research archive</div><h1>What does a foreign approval let a medicine do?</h1><p class="lead">Countries allow different amounts of foreign regulatory work to support a domestic decision. The recurring differences concern access to assessment reports, product sameness, local checks and the regulator’s remaining discretion.</p>
<div class="stats"><div class="stat"><b>250</b><span>country/area JSONs and broad searches</span></div><div class="stat"><b>{C['jurisdictions_individually_reviewed']}</b><span>individual jurisdiction text reviews</span></div><div class="stat"><b>{C['national_authorisation_texts']}</b><span>selected authorisation pathway texts</span></div><div class="stat"><b>{L['papers_in_synthesis']}</b><span>published studies synthesised</span></div></div>
<nav><a href="#backlog">New reviews</a><a href="#findings">Main findings</a><a href="#published">Published comparisons</a><a href="#wording">Exact wording</a><a href="#audit">All 250 jurisdictions</a><a href="#methods">Methods and completion</a></nav>
<p class="small">Snapshot: {e(S['checkpoint_utc'])}. This on-hand review expands the sample from 87 to {C["jurisdictions_individually_reviewed"]} jurisdictions and from 138 to {C["individual_clauses"]} individual passages. There are also 9 shared-procedure passages, reviewed once.</p></header>
<main><section id="backlog"><h2>What this review added</h2><p>The previous 66 selected national approval-pathway texts have expanded to {C['national_authorisation_texts']}. We added {V['new_jurisdictions']} individually reviewed jurisdictions and replaced Canada's older pilot description with a ministerial-order text. The archive now contains {V['distinct_selected_raw_documents']} distinct original documents behind {C['individual_clauses']} national passages across {C['jurisdictions_individually_reviewed']} jurisdictions.</p><details><summary>New country and area reviews</summary><p>{e(new_names)}</p></details><div class="grid"><div class="card"><h3>Reliance also runs between emerging markets</h3><p>Zambia's notice dated 22 July 2025 implements recognition of Egyptian-approved medicines manufactured in Egypt. It specifies a 30-working-day target, an approved dossier and quality documents. This adds a concrete South–South connection beyond reliance on FDA or EMA.</p><a href="https://www.zamra.co.zm/wp-content/uploads/2025/07/ZAMRA-EDA-MoU-Public-Notice-July-2025.pdf">ZAMRA implementation notice</a></div><div class="card"><h3>Written time savings can be measured directly</h3><p>Bosnia and Herzegovina's Articles 32–33 specify 150 days for qualifying products reviewed through European CP/MRP/DCP procedures versus 210 days otherwise. The 60-day difference is a legal timetable difference; realised approval times require application records.</p><a href="https://www.sluzbenilist.ba/page/akt/7iXyEjXU2IQ%3D">Official Gazette rulebook</a></div><div class="card"><h3>Permission can be limited to a particular access channel</h3><p>Bahrain recognises GCC central registration after domestic formalities. Its separate 2022 rule permits specified import access for unregistered foreign-approved medicines. Slovenia's urgent route concerns older, well-established medicines. These routes must retain their product and access restrictions.</p></div><div class="card"><h3>Versions and encoding matter</h3><p>Turkey's 2022 and 2023 texts remain separate. Armenia's 2019 decree specifies 31 calendar days for simplified registration, including 21 days of assessment, with extensions and clock stops. Bahrain's Arabic HTML was re-extracted using correct UTF-8 decoding; original bytes and previous extraction are retained.</p></div></div><p><a href="remaining_review/document_review_ledger.csv">Document screening and review ledger</a> · <a href="remaining_review/review_summary.json">Review expansion counts and methods</a></p></section><section id="findings"><h2>Foreign approval usually comes with conditions</h2>
<div class="grid"><div class="card"><h3>Information can be the binding constraint</h3><p>{by['reports']['count']} of {R['legal_n']} selected authorisation texts expressly address assessment reports or regulatory information; {by['unredacted']['count']} mention unredacted or non-public material. A public approval date alone may leave the applicant unable to use the route.</p></div><div class="card"><h3>Domestic review often remains</h3><p>{by['discretion']['count']} texts expressly retain domestic decision, refusal or further-review powers; {by['sameness']['count']} address product or dossier sameness. A prior foreign approval supports a conditional domestic process.</p></div><div class="card"><h3>Different institutions use different clocks</h3><p>{by['decision_clock']['count']} texts state a procedural clock. A report-preparation deadline, a regulator review target and time until the final national decision measure different stages. Algeria’s 2026 guideline gives an emergency assessment clock while retaining conventional deadlines for other eligible products.</p></div><div class="card"><h3>A clearer legal map than a single yes/no variable</h3><p>The archive distinguishes national pathways, narrower functions, official explanations, historical rules, shared systems and programme participation. These categories help identify what a reform actually changes.</p></div></div>
<figure><img src="{im('legal_wording_conditions.png')}" alt="Express legal conditions in selected authorisation pathway texts"><figcaption>Counts describe wording present in selected passages and versions. A requirement not found in the selected passage is not coded as legally absent. Statutes, regulations and official procedure guidance remain separately labelled.</figcaption></figure><details><summary>Countries behind each count</summary><div class="scroll"><table><thead><tr><th>Wording feature</th><th>Texts</th><th>Jurisdictions</th></tr></thead><tbody>{feature_rows}</tbody></table></div></details>
</section><section id="published"><h2>Do the published studies agree?</h2><p>We downloaded nine original supporting files and linked {L["country_comparison_records"]} published observations, with country matches in {L["countries_with_published_comparison"]} JSONs and one unresolved published country label. The closest comparisons distinguish written authority, practical use and product scope.</p>
<div class="scroll"><table><thead><tr><th>Study</th><th>What it reports</th><th>Check against our archive</th></tr></thead><tbody>{lit_rows}</tbody></table></div>
<div class="callout"><strong>Three informative differences.</strong> The 2025 industry table describes practical reliance without a legal framework in Tunisia and Morocco, and a route not applied in practice in Turkey. The older Latin American study’s negative Brazil classification predates our 2024 Anvisa text. These are recorded as scope, implementation or timing differences.</div>
<p><a href="full250/literature/Literature_Crosscheck.html">Open the full literature comparison, all {L["papers_in_synthesis"]} studies and supporting-file downloads →</a></p>
</section><section id="complexity"><h2>Recurring wording and complexity</h2><p>We analyse {R['nlp_n']} sufficiently long, selected English texts: {nlp_legal} selected national pathways and {R['nlp_n']-nlp_legal} narrower or explanatory texts. Their vocabulary describes recurring approaches to foreign assessment, national decisions and shared procedures. Highly similar European procedure pages reflect a common legal family.</p>
<div class="grid"><figure><img src="{im('wording_similarity.png')}" alt="Similarity of selected English reliance texts"><figcaption>Nearby labels share vocabulary after country and agency names are removed. Brown marks the identified European shared-authorisation family. Axes measure text variation.</figcaption></figure><div class="card"><h3>Checks on the text results</h3><p>The exploratory topic model selects {R['topics']['selected_k']} topics by held-out fit, but the global grouping is unstable. Its median agreement across random seeds is {R['topics']['median_adjusted_rand_index']:.2f}; excluding all identified European shared-system texts gives {K['two_topic_median_ari_excluding_new_family']:.2f}. Topic stability must be interpreted alongside common institutions and source selection.</p><p>The median selected English passage has about {orig['median_words_per_sentence']:.0f} words per sentence after known official translations are excluded. Sentence splitting, document genre and excerpt selection affect this measure. English website availability alone does not establish the original drafting language.</p><p>The median authorisation text contains {K['requirement_dimension_median']:.0f} of our 11 coded requirement dimensions. This measures documented dimensions in the selected text; it does not estimate compliance costs.</p></div></div>
<p class="small">The separate translation sensitivity uses {R['translation_sensitivity']['additional_checked_translation_n']} countries with complete checked research renderings. Unchecked machine translations are excluded. Shared rules and source-language translations are labelled, and translated readability is not pooled with original-language metrics.</p>
</section><section id="wording"><h2>Read the exact wording</h2><p>Choose one country to see all its reviewed passages. Original extracted wording, source URLs, offsets, hashes and version notes are retained. OCR remains a separate machine transcription; the original scan controls.</p><label for="countrySelect">Choose a country or area</label><select id="countrySelect" aria-label="Choose one country or area"></select><input id="quoteSearch" placeholder="Search words, article or feature"><button id="resetQuotes">Reset</button><p id="clauseCount" class="small"></p><div id="clauseList"></div><button id="moreQuotes">Show more passages</button></section>
<section id="audit"><h2>All 250 countries and areas</h2><p>All 250 have broad search responses and individual JSON files. We retain {250-C['by_status']['no_qualifying_passage_on_hand']} with some directly reviewed or shared/programme evidence, and {C['by_status']['no_qualifying_passage_on_hand']} without a qualifying passage on hand. Search results about another country remain discovery leads and do not change that classification.</p><input id="auditSearch" placeholder="Find a country"><select id="auditStatus"><option value="">All evidence categories</option></select><p id="auditCount" class="small"></p><div class="scroll"><table><thead><tr><th>Country/area</th><th>Reviewed evidence</th><th>Passages</th><th>Discovery checkpoint</th><th>Scope/version note</th></tr></thead><tbody id="auditRows"></tbody></table></div></section>
<section id="methods"><h2>What is complete, and what resumes next?</h2><p>{S['completed_query_tasks']:,} of {S['planned_query_tasks']:,} planned query tasks have saved responses at this checkpoint, including {S['country_year_tasks_completed']:,} of {S['country_year_tasks']:,} country-year searches for 2000–2026. The 2026 year is partial. Search years are query keywords and are never used as legal effective dates.</p><p>Google’s browser pilot produced one usable nine-result sample, then incomplete rendering and traffic challenges. Those records are preserved. The broader run uses the built-in web search service, whose underlying engine is not exposed; returned ordering is labelled accordingly. If fewer than ten results are returned, we save the available results and report the shortfall.</p><p>The new discovery collection has {S['unique_downloaded_raw_hashes']:,} distinct downloaded source byte hashes, including unreviewed or irrelevant material. We recovered {S['ocr_completed_pages']:,} scanned/low-text pages across {S['ocr_raw_pdf_hashes']} distinct PDF hashes. This is text recovery, not an equal number of verified laws.</p><p>The on-hand union contains {V['on_hand_distinct_raw_documents_screened']:,} distinct raw documents screened for relevant wording. Screening is distinguished from contextual review. The ledger marks {V['screening_status_counts'].get('Screened: possible relevant wording; contextual review remains',0):,} documents with possible relevant wording still requiring contextual review. Some are surveys, foreign-country rules or unrelated uses of recognition; they are not silently classified as national laws.</p>
<div class="callout amber">The historical country-year search remains incomplete: {S['pending_query_tasks']:,} query tasks are pending in the saved queue. Pending searches are null. “No documented measure found” is kept separate from a verified legal absence. No new annual adoption dates are inferred from current documents, year keywords or survey participation.</div>
<p><a href="Country_Regulation_JSONs.zip">Download all country JSONs and research code</a> · <a href="full250/resume_queue.json">Resumable query queue</a> · <a href="full250/country_year_discovery.csv">Country-year discovery matrix</a> · <a href="full250/source_manifest.json">New source manifest</a> · <a href="full250/analysis/text_analysis_results.json">Text-analysis outputs</a> · <a href="full250/analysis/family_sensitivity.json">Legal-family sensitivity</a></p>
<p class="small">Purpose: distinguish what domestic regulators may accept, what applicants must supply and what still gets reviewed locally. The current exercise measures legal wording and published implementation evidence; no causal effect on prices or approval time is estimated by the wording model.</p></section></main>
<footer><small>Public sources and original-language documents preserved. Assistant contextual review and checked research translations are labelled; this is a research archive, not legal certification.</small></footer>
<script>const CLAUSES={j(Q+SH)},AUDIT={j(A)};const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));const labels={{national_rule:'Individual authorisation pathway',limited_scope_or_framework:'Limited function / framework',official_policy_explanation:'Official policy explanation',historical_rule:'Historical rule',shared_regional_rule_only:'Shared regional rule only',programme_participation_only:'WHO programme only',no_qualifying_passage_on_hand:'No qualifying passage on hand'}};const countries=[...AUDIT.map(a=>[a.iso3,a.country]),...new Map(CLAUSES.filter(q=>!AUDIT.some(a=>a.iso3===q.iso3)).map(q=>[q.iso3,q.country])).entries()].sort((a,b)=>a[1].localeCompare(b[1]));$('countrySelect').innerHTML=countries.map(([id,n])=>`<option value="${{esc(id)}}">${{esc(n)}} (${{esc(id)}})</option>`).join('');$('countrySelect').value='GBR';let limit=Number.MAX_SAFE_INTEGER;
function selectClauses(){{let c=$('countrySelect').value,t=$('quoteSearch').value.toLowerCase().trim();return CLAUSES.filter(q=>(!c||q.iso3===c)&&(!t||[q.country,q.verbatim_extracted_text,q.section_article,q.research_interpretation,...q.feature_tags].join(' ').toLowerCase().includes(t)));}}
function renderClauses(){{let rr=selectClauses();$('clauseCount').textContent=`${{rr.length}} passages; showing ${{Math.min(limit,rr.length)}}`;$('clauseList').innerHTML=rr.slice(0,limit).map(q=>{{let tr=q.translation_review;return `<article class="clause"><h3>${{esc(q.country)}} <small>${{esc(q.clause_id)}}</small></h3><span class="tag">${{esc(labels[q.evidence_tier]||q.evidence_tier)}}</span><span class="tag">${{esc(q.language)}}</span><p class="small">${{esc(q.section_article||q.role)}} · ${{esc(q.language_status)}}</p><div class="verbatim" dir="auto">${{esc(q.verbatim_extracted_text||q.display_text)}}</div>${{tr?.approved_for_display?`<details><summary>Checked English research translation</summary><div class="verbatim">${{esc(tr.checked_translation)}}</div><p class="small">${{esc(tr.check_note)}} Assistant checked; original text controls.</p></details>`:q.language!=='en'?`<p class="small">${{tr?'Machine rendering quarantined: '+esc(tr.check_note):'Original wording retained; no approved machine translation displayed.'}}</p>`:''}}<p>${{esc(q.research_interpretation||'Read this passage with the scope and conditions in the linked source.')}}</p><p class="small">${{esc(q.version_alignment)}}</p><p><a href="${{esc(q.source_url)}}" target="_blank" rel="noopener">Source document</a>${{AUDIT.some(a=>a.iso3===q.iso3)?` · <a href="countries/${{esc(q.iso3)}}.json">Country JSON</a>`:''}}</p><details><summary>Offsets, hashes and feature codes</summary><pre>${{esc(JSON.stringify({{document_id:q.document_id,start_offset:q.start_offset,end_offset:q.end_offset,pdf_page:q.pdf_page,raw_sha256:q.raw_sha256,text_sha256:q.text_sha256,feature_tags:q.feature_tags}},null,2))}}</pre></details></article>`;}}).join('')||'<p>No individually reviewed passage matches. The country JSON preserves discovery results, shared/programme material and pending tasks.</p>';$('moreQuotes').style.display=rr.length>limit?'inline-block':'none';}}
$('countrySelect').addEventListener('input',()=>{{$('quoteSearch').value='';renderClauses();}});$('quoteSearch').addEventListener('input',renderClauses);$('resetQuotes').addEventListener('click',()=>{{$('countrySelect').value='GBR';$('quoteSearch').value='';limit=Number.MAX_SAFE_INTEGER;renderClauses();}});$('moreQuotes').addEventListener('click',()=>{{limit+=8;renderClauses();}});$('auditStatus').innerHTML+=[...new Set(AUDIT.map(a=>a.review_status))].map(s=>`<option value="${{esc(s)}}">${{esc(labels[s]||s)}}</option>`).join('');function selectAudit(){{let t=$('auditSearch').value.toLowerCase().trim(),s=$('auditStatus').value;return AUDIT.filter(a=>(!s||s===a.review_status)&&(!t||[a.country,a.iso3,a.reason].join(' ').toLowerCase().includes(t)));}}function renderAudit(){{let rr=selectAudit();$('auditCount').textContent=`${{rr.length}} of 250 countries / areas`;$('auditRows').innerHTML=rr.map(a=>`<tr><td><a href="countries/${{esc(a.iso3)}}.json">${{esc(a.country)}}</a><br><small>${{esc(a.iso3)}}</small></td><td>${{esc(labels[a.review_status]||a.review_status)}}</td><td>${{a.individual_clauses}}</td><td>${{a.search_records}} saved searches; ${{a.year_searches}}/27 years; ${{a.pending_searches}} pending<br><small>${{a.published_comparisons}} published comparisons; ${{a.new_source_responses}} source responses</small></td><td>${{esc(a.reason)}}</td></tr>`).join('');}}for(let id of ['auditSearch','auditStatus'])$(id).addEventListener('input',renderAudit);renderClauses();renderAudit();</script></body></html>'''
(O/'Regulatory_Reliance_Text_Results.html').write_text(text,encoding='utf8');print('Saved current report',len(text.encode()),'bytes,',len(Q+SH),'passages')

